const raw = $json.body ?? $json;
let body = raw;
if (typeof raw === 'string') {
  try { body = JSON.parse(raw); } catch { body = {}; }
}
const action = String(body.action ?? 'preview').toLowerCase();
const timezone = String(body.timezone ?? 'Asia/Seoul');
const allowedActions = ['preview', 'confirm', 'cancel'];
let error = null;
try { new Intl.DateTimeFormat('en-US', { timeZone: timezone }).format(); } catch { error = 'timezone은 올바른 IANA 시간대여야 합니다.'; }
if (!allowedActions.includes(action)) error = 'action은 preview, confirm, cancel 중 하나여야 합니다.';
if (action === 'preview' && (!body.message || !String(body.message).trim())) error = 'message는 필수입니다.';
if (action === 'confirm' && (!body.request_id || !Array.isArray(body.items))) error = 'confirm에는 request_id와 items 배열이 필요합니다.';
return [{ json: error ? { status: 'invalid_request', error, http_status: 400 } : { action, message: String(body.message ?? '').trim(), user: String(body.user ?? 'anonymous'), timezone, request_id: body.request_id ?? null, items: Array.isArray(body.items) ? body.items : [] } }];

const input = $json;
const pad = n => String(n).padStart(2, '0');
const localNow = new Date(new Date().toLocaleString('en-US', { timeZone: input.timezone }));
const dateOnly = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const dateFor = text => {
  const d = new Date(localNow);
  if (/모레/.test(text)) d.setDate(d.getDate() + 2);
  else if (/내일/.test(text)) d.setDate(d.getDate() + 1);
  else if (/오늘/.test(text)) {}
  else {
    const names = ['일', '월', '화', '수', '목', '금', '토'];
    const m = text.match(/([월화수목금토일])요일/);
    if (m) { const target = names.indexOf(m[1]); let diff = (target - d.getDay() + 7) % 7; if (diff === 0) diff = 7; d.setDate(d.getDate() + diff); }
    else return null;
  }
  return dateOnly(d);
};
const offsetFor = (date, timeZone) => {
  try {
    const parts = new Intl.DateTimeFormat('en-US', { timeZone, timeZoneName: 'longOffset' }).formatToParts(date);
    const value = parts.find(p => p.type === 'timeZoneName')?.value || 'GMT+00:00';
    return value.replace('GMT', '') || '+00:00';
  } catch { return '+00:00'; }
};
const clauses = input.message.split(/(?:[.!?]+\s*|\n+|,\s*)/).map(v => v.trim()).filter(Boolean);
const items = [];
for (const clause of clauses) {
  const clean = clause.replace(/^(그리고|또|또한)\s*/, '').trim();
  if (!clean) continue;
  if (/메모|기록해|기억해/.test(clean)) {
    const title = clean.replace(/(도)?\s*(메모|기록|기억)(해|해줘|해 줘|해 주세요|해주세요)?[\s.]*$/g, '').trim() || clean;
    items.push({ type: 'note', route: 'notes', title, content: null, needs_input: true, source_text: clause });
    continue;
  }
  const amountMatch = clean.match(/([0-9][0-9,]*)\s*원/);
  if (amountMatch && /(썼|결제|구매|지출|냈)/.test(clean)) {
    const description = clean.replace(/오늘|어제|내일/g, '').replace(/([0-9][0-9,]*)\s*원/g, '').replace(/(으로|로)?\s*(썼어|썼다|결제했어|결제했다|구매했어|구매했다|지출했어|지출했다|냈어|냈다)/g, '').trim();
    items.push({ type: 'expense', route: 'expenses', category: /교재|책|강의|교육/.test(clean) ? '교육' : '미분류', amount: Number(amountMatch[1].replace(/,/g, '')), currency: 'KRW', description: description || '지출', needs_input: false, source_text: clause });
    continue;
  }
  if (/(예약|약속|회의|미팅|진료)/.test(clean)) {
    const date = dateFor(clean);
    const tm = clean.match(/(?:(오전|오후)\s*)?(\d{1,2})시(?:\s*(\d{1,2})분)?/);
    let startsAt = null;
    if (date && tm) { let hour = Number(tm[2]); if (tm[1] === '오후' && hour < 12) hour += 12; if (tm[1] === '오전' && hour === 12) hour = 0; const offset = offsetFor(new Date(), input.timezone); startsAt = `${date}T${pad(hour)}:${pad(Number(tm[3] || 0))}:00${offset}`; }
    const title = clean.replace(/오늘|내일|모레|[월화수목금토일]요일/g, '').replace(/(?:(오전|오후)\s*)?\d{1,2}시(?:\s*\d{1,2}분)?(?:에)?/g, '').trim();
    items.push({ type: 'calendar', route: 'calendar', title: title || clean, starts_at: startsAt, timezone: input.timezone, needs_input: !startsAt, source_text: clause });
    continue;
  }
  if (/(까지|할 ?일|해야|만들|작성|제출|보내|준비)/.test(clean)) {
    const dueDate = dateFor(clean);
    const title = clean.replace(/오늘|내일|모레|[월화수목금토일]요일/g, '').replace(/까지/g, '').replace(/(해야 해|해야해|해 줘|해주세요)[\s.]*$/g, '').trim();
    items.push({ type: 'task', route: 'tasks', title: title || clean, due_date: dueDate, needs_input: !dueDate, source_text: clause });
    continue;
  }
  items.push({ type: 'unknown', route: 'questions', title: clean, question: '일정, 할 일, 지출, 메모 중 어떤 종류인지 알려 주세요.', needs_input: true, source_text: clause });
}
const requestId = `inbox_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
const counts = items.reduce((acc, item) => { acc[item.route] = (acc[item.route] || 0) + 1; return acc; }, {});
return [{ json: { status: 'confirmation_required', request_id: requestId, user: input.user, timezone: input.timezone, items, route_counts: counts, confirmation: { webhook: '/webhook/personal-inbox', method: 'POST', body: { action: 'confirm', request_id: requestId, items } } } }];

const input = $json;
const allowed = new Set(['calendar', 'task', 'expense', 'note']);
const errors = [];
input.items.forEach((item, index) => {
  if (!item || typeof item !== 'object') { errors.push(`items[${index}]는 객체여야 합니다.`); return; }
  if (!allowed.has(item.type)) errors.push(`items[${index}].type이 올바르지 않습니다.`);
  if (item.needs_input === true) errors.push(`items[${index}]는 추가 정보가 필요합니다.`);
  if (item.type === 'calendar' && (!item.title || !item.starts_at || Number.isNaN(Date.parse(item.starts_at)))) errors.push(`items[${index}] 일정의 title 또는 starts_at이 올바르지 않습니다.`);
  if (item.type === 'task' && !item.title) errors.push(`items[${index}] 할 일의 title이 필요합니다.`);
  if (item.type === 'expense' && (!Number.isFinite(Number(item.amount)) || Number(item.amount) <= 0 || !item.description)) errors.push(`items[${index}] 지출의 amount 또는 description이 올바르지 않습니다.`);
  if (item.type === 'note' && (!item.title || !item.content)) errors.push(`items[${index}] 메모의 title과 content가 필요합니다.`);
});
return [{ json: errors.length ? { status: 'confirmation_rejected', request_id: input.request_id, error: '확정할 수 없는 항목이 있습니다.', details: errors, http_status: 400 } : { ...input, confirmation_valid: true } }];

const input = $json;
const targets = { calendar: 'fake_calendar', task: 'fake_task_list', expense: 'fake_expense_ledger', note: 'fake_notes' };
const savedAt = new Date().toISOString();
const results = input.items.map((item, index) => ({ index, type: item.type, target: targets[item.type], status: 'saved', fake_id: `${item.type}_${Date.now()}_${index + 1}`, saved_at: savedAt }));
return [{ json: { status: 'completed', request_id: input.request_id, saved_count: results.length, failed_count: 0, results } }];
